130→// UninstallHooks removes the Entire hooks config file and IDE hook files.
131→func (k *KiroAgent) UninstallHooks(ctx context.Context) error {
132→	worktreeRoot, err := paths.WorktreeRoot(ctx)
133→	if err != nil {
134→		worktreeRoot = "."
135→	}
136→
137→	// Remove CLI agent file
138→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
139→	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
140→		return fmt.Errorf("failed to remove hooks config: %w", err)
141→	}
142→
143→	// Remove IDE hook files
144→	for _, def := range ideHookDefs {
145→		idePath := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
146→		if err := os.Remove(idePath); err != nil && !os.IsNotExist(err) {
147→			return fmt.Errorf("failed to remove IDE hook %s: %w", def.Filename, err)
148→		}
149→	}
150→
151→	return nil
152→}
