154→// AreHooksInstalled checks if Entire hooks are installed.
155→// Returns true if EITHER CLI agent hooks or IDE hooks are present.
156→func (k *KiroAgent) AreHooksInstalled(ctx context.Context) bool {
157→	worktreeRoot, err := paths.WorktreeRoot(ctx)
158→	if err != nil {
159→		worktreeRoot = "."
160→	}
161→
162→	// Check CLI agent hooks
163→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
164→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
165→	if err == nil {
166→		var file kiroAgentFile
167→		if json.Unmarshal(data, &file) == nil {
168→			if hasEntireHook(file.Hooks.AgentSpawn) ||
169→				hasEntireHook(file.Hooks.UserPromptSubmit) ||
170→				hasEntireHook(file.Hooks.Stop) {
171→				return true
172→			}
173→		}
174→	}
175→
176→	// Check IDE hooks — any Entire IDE hook file means hooks are installed
177→	return anyIDEHookPresent(worktreeRoot)
178→}
