180→// GetSupportedHooks returns the hook types Kiro supports.
181→func (k *KiroAgent) GetSupportedHooks() []agent.HookType {
182→	return []agent.HookType{
183→		agent.HookSessionStart,
184→		agent.HookUserPromptSubmit,
185→		agent.HookPreToolUse,
186→		agent.HookPostToolUse,
187→		agent.HookStop,
188→	}
189→}
