233→// installIDEHooks creates .kiro/hooks/*.kiro.hook files for the Kiro IDE.
234→func installIDEHooks(worktreeRoot, cmdPrefix string) (int, error) {
235→	dir := filepath.Join(worktreeRoot, ".kiro", ideHooksDir)
236→	if err := os.MkdirAll(dir, 0o750); err != nil {
237→		return 0, fmt.Errorf("failed to create .kiro/hooks directory: %w", err)
238→	}
239→
240→	for _, def := range ideHookDefs {
241→		hook := kiroIDEHookFile{
242→			Enabled:     true,
243→			Name:        def.Filename,
244→			Description: "Entire CLI " + def.TriggerType + " hook",
245→			Version:     ideHookVersion,
246→			When: kiroIDEHookWhen{
247→				Type: def.TriggerType,
248→			},
249→			Then: kiroIDEHookThen{
250→				Type:    "command",
251→				Command: cmdPrefix + def.CLIVerb,
252→			},
253→		}
254→
255→		data, err := jsonutil.MarshalIndentWithNewline(hook, "", "  ")
256→		if err != nil {
257→			return 0, fmt.Errorf("failed to marshal IDE hook %s: %w", def.Filename, err)
258→		}
259→
260→		path := filepath.Join(dir, def.Filename+ideHookFileSuffix)
261→		if err := os.WriteFile(path, data, 0o600); err != nil {
262→			return 0, fmt.Errorf("failed to write IDE hook %s: %w", def.Filename, err)
263→		}
264→	}
265→
266→	return len(ideHookDefs), nil
267→}
268→
269→// allIDEHooksPresent checks that all 4 IDE hook files exist and have correct commands.
270→func allIDEHooksPresent(worktreeRoot string, localDev bool) bool {
271→	var cmdPrefix string
272→	if localDev {
273→		cmdPrefix = localDevCmdPrefix + "hooks kiro "
274→	} else {
275→		cmdPrefix = prodHookCmdPrefix
276→	}
277→
278→	for _, def := range ideHookDefs {
279→		path := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
280→		data, err := os.ReadFile(path) //nolint:gosec // path constructed from repo root
281→		if err != nil {
282→			return false
283→		}
284→		var hook kiroIDEHookFile
285→		if err := json.Unmarshal(data, &hook); err != nil {
286→			return false
287→		}
288→		if hook.Then.Command != cmdPrefix+def.CLIVerb {
289→			return false
290→		}
291→	}
292→	return true
293→}
294→
295→// anyIDEHookPresent checks if any Entire IDE hook file exists.
296→func anyIDEHookPresent(worktreeRoot string) bool {
297→	for _, def := range ideHookDefs {
298→		path := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
299→		data, err := os.ReadFile(path) //nolint:gosec // path constructed from repo root
300→		if err != nil {
301→			continue
302→		}
303→		var hook kiroIDEHookFile
304→		if json.Unmarshal(data, &hook) == nil && isEntireIDEHook(hook) {
305→			return true
306→		}
307→	}
308→	return false
309→}
310→
311→// isEntireIDEHook checks if an IDE hook file belongs to Entire.
312→func isEntireIDEHook(hook kiroIDEHookFile) bool {
313→	return strings.HasPrefix(hook.Name, "entire-") && isEntireHook(hook.Then.Command)
314→}
